/* Cross-page documentation search.
 *
 * Reads window.__DOCS_SEARCH (docs/site/search-index.js, generated by
 * scripts/search_index.py) and turns every `.docsearch` container into a search
 * box with a results dropdown that deep-links to `page.html#section`.
 *
 * Why not fetch(): the pages are self-contained and must work from `file://`,
 * where fetch() and modules are blocked. The index is a committed script, so a
 * plain <script> tag loads it offline. See S25.
 */
(function () {
  var DATA = window.__DOCS_SEARCH || [];

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function terms(q) {
    return q.toLowerCase().split(/[^a-z0-9_.]+/).filter(Boolean);
  }
  // Every term must appear (AND); title hits weigh more than body hits.
  function score(rec, ts) {
    var title = (rec.t || "").toLowerCase();
    var body = (rec.x || "").toLowerCase();
    var s = 0;
    for (var i = 0; i < ts.length; i++) {
      var t = ts[i];
      var inTitle = title.indexOf(t) !== -1;
      var inBody = body.indexOf(t) !== -1;
      if (!inTitle && !inBody) return -1;
      s += (title.split(t).length - 1) * 10 + (body.split(t).length - 1);
    }
    return s;
  }
  function snippet(rec, ts) {
    var body = rec.x || "";
    var low = body.toLowerCase();
    var at = -1;
    for (var i = 0; i < ts.length; i++) {
      var p = low.indexOf(ts[i]);
      if (p >= 0 && (at < 0 || p < at)) at = p;
    }
    if (at < 0) at = 0;
    var start = Math.max(0, at - 40);
    var end = Math.min(body.length, at + 130);
    return (start > 0 ? "…" : "") + esc(body.slice(start, end)) + (end < body.length ? "…" : "");
  }

  var CSS =
    ".docsearch{position:relative}" +
    ".ds-results{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:50;" +
    "background:var(--surface);border:1px solid var(--line3);border-radius:10px;" +
    "box-shadow:var(--shadow);max-height:min(62vh,440px);overflow:auto;padding:6px}" +
    ".ds-hit{display:block;padding:7px 9px;border-radius:8px;text-decoration:none;color:var(--ink)}" +
    ".ds-hit:hover,.ds-hit:focus{background:var(--surface2);text-decoration:none;outline:none}" +
    ".ds-page{display:inline-block;font-size:.66rem;font-weight:700;letter-spacing:.07em;" +
    "text-transform:uppercase;color:var(--accent);margin-right:7px}" +
    ".ds-title{font-weight:650;color:var(--ink)}" +
    ".ds-snip{display:block;font-size:.78rem;color:var(--muted);margin-top:2px}" +
    ".ds-empty{padding:8px 10px;color:var(--muted);font-size:.85rem}";

  function injectCSS() {
    if (document.getElementById("docs-search-css")) return;
    var style = document.createElement("style");
    style.id = "docs-search-css";
    style.textContent = CSS;
    document.head.appendChild(style);
  }

  function init(box) {
    var input = box.querySelector("input");
    var results = box.querySelector(".ds-results");
    if (!input || !results) return;

    function close() {
      results.hidden = true;
      results.innerHTML = "";
    }
    function render() {
      var q = input.value.trim();
      if (q.length < 2) return close();
      var ts = terms(q);
      var hits = [];
      for (var i = 0; i < DATA.length; i++) {
        var sc = score(DATA[i], ts);
        if (sc >= 0) hits.push([sc, DATA[i]]);
      }
      hits.sort(function (a, b) { return b[0] - a[0]; });
      hits = hits.slice(0, 12);
      results.hidden = false;
      if (!hits.length) {
        results.innerHTML = '<div class="ds-empty">No matches for “' + esc(q) + '”.</div>';
        return;
      }
      results.innerHTML = hits
        .map(function (h) {
          var r = h[1];
          return (
            '<a class="ds-hit" href="' + esc(r.p) + "#" + esc(r.a) + '">' +
            '<span class="ds-page">' + esc(r.p.replace(/\.html$/, "")) + "</span>" +
            '<span class="ds-title">' + esc(r.t || r.a) + "</span>" +
            '<span class="ds-snip">' + snippet(r, ts) + "</span></a>"
          );
        })
        .join("");
    }
    function move(delta) {
      var links = results.querySelectorAll("a.ds-hit");
      if (!links.length) return;
      var idx = -1;
      for (var i = 0; i < links.length; i++) if (links[i] === document.activeElement) idx = i;
      var next = Math.min(links.length - 1, Math.max(0, idx + delta));
      links[next].focus();
    }

    input.addEventListener("input", render);
    input.addEventListener("focus", render);
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { input.value = ""; close(); input.blur(); }
      else if (e.key === "ArrowDown") { e.preventDefault(); move(1); }
      else if (e.key === "ArrowUp") { e.preventDefault(); move(-1); }
      else if (e.key === "Enter") {
        var first = results.querySelector("a.ds-hit");
        if (first) window.location.href = first.getAttribute("href");
      }
    });
    document.addEventListener("click", function (e) {
      if (!box.contains(e.target)) close();
    });
  }

  function ready() {
    if (!DATA.length) return; // index missing — leave the page exactly as it was
    injectCSS();
    var boxes = document.querySelectorAll(".docsearch");
    for (var i = 0; i < boxes.length; i++) init(boxes[i]);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", ready);
  else ready();
})();
